with with_prev as (select *, lag(started_at) over (partition by customer_id order by started_at, id) as prev_started_at from sessions), gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval 14 days then 1 else 0 end as is_new_session from with_prev) select *, sum(is_new_session) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as island_id from gaps
